create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade,username text unique not null check(length(username) between 3 and 24),bio text default '',cover_color text default '#18213a',accent_color text default '#245edb',wallpaper text default 'bliss',layout text default 'classic',level int default 1,xp int default 0);
create table public.user_roles(user_id uuid primary key references auth.users on delete cascade,role text check(role in('owner','admin','moderator','support')) not null);
create table public.posts(id uuid primary key default gen_random_uuid(),author_id uuid references profiles on delete cascade not null,body text not null check(length(body) between 1 and 3000),status text default 'published' check(status in('published','removed','hidden')),created_at timestamptz default now());
create table public.likes(post_id uuid references posts on delete cascade,user_id uuid references profiles on delete cascade,created_at timestamptz default now(),primary key(post_id,user_id));
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid references posts on delete cascade,author_id uuid references profiles on delete cascade,body text not null check(length(body) between 1 and 1000),created_at timestamptz default now());
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references profiles,post_id uuid references posts on delete set null,reason text not null,status text default 'open',created_at timestamptz default now());
create table public.topics(id uuid primary key default gen_random_uuid(),author_id uuid references profiles,title text not null,body text not null,created_at timestamptz default now());
create table public.conversations(id uuid primary key default gen_random_uuid(),user_a uuid references profiles,user_b uuid references profiles,check(user_a<user_b),unique(user_a,user_b));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid references conversations on delete cascade,sender_id uuid references profiles,body text not null check(length(body) between 1 and 4000),created_at timestamptz default now());
create table public.moderation_log(id uuid primary key default gen_random_uuid(),moderator_id uuid references profiles,action text not null,target_post uuid,reason text not null,created_at timestamptz default now());
create table public.communities(id uuid primary key default gen_random_uuid(),name text unique,description text default '',category text default 'General');
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_roles where user_id=auth.uid() and role in('owner','admin','moderator'))$$;
create function public.get_or_create_conversation(other_user uuid) returns uuid language plpgsql security definer set search_path=public as $$declare a uuid;b uuid;cid uuid;begin if auth.uid() is null or other_user=auth.uid() then raise exception 'Invalid user';end if;a:=least(auth.uid(),other_user);b:=greatest(auth.uid(),other_user);insert into conversations(user_a,user_b) values(a,b) on conflict(user_a,user_b) do update set user_a=excluded.user_a returning id into cid;return cid;end$$;
create function public.moderate_remove_post(target_post uuid,removal_reason text) returns void language plpgsql security definer set search_path=public as $$begin if not is_admin() then raise exception 'Not authorized';end if;if length(trim(removal_reason))<3 then raise exception 'Reason required';end if;update posts set status='removed' where id=target_post;insert into moderation_log(moderator_id,action,target_post,reason) values(auth.uid(),'remove_post',target_post,trim(removal_reason));end$$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,username) values(new.id,coalesce(new.raw_user_meta_data->>'username','member_'||substr(new.id::text,1,8)));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure handle_new_user();
alter table profiles enable row level security;alter table user_roles enable row level security;alter table posts enable row level security;alter table likes enable row level security;alter table comments enable row level security;alter table reports enable row level security;alter table topics enable row level security;alter table conversations enable row level security;alter table messages enable row level security;alter table moderation_log enable row level security;alter table communities enable row level security;
create policy "profile read" on profiles for select to authenticated using(true);create policy "profile update self" on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "roles read" on user_roles for select to authenticated using(user_id=auth.uid() or is_admin());
create policy "posts read" on posts for select to authenticated using(status='published' or is_admin());create policy "post own" on posts for insert to authenticated with check(author_id=auth.uid());
create policy "likes read" on likes for select to authenticated using(true);create policy "likes own" on likes for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "comments read" on comments for select to authenticated using(true);create policy "comments own" on comments for insert to authenticated with check(author_id=auth.uid());
create policy "reports own" on reports for insert to authenticated with check(reporter_id=auth.uid());create policy "reports admin" on reports for select to authenticated using(is_admin());
create policy "topics read" on topics for select to authenticated using(true);create policy "topics own" on topics for insert to authenticated with check(author_id=auth.uid());
create policy "conversations members" on conversations for select to authenticated using(auth.uid() in(user_a,user_b));create policy "conversation create" on conversations for insert to authenticated with check(auth.uid() in(user_a,user_b));
create policy "messages members read" on messages for select to authenticated using(exists(select 1 from conversations c where c.id=conversation_id and auth.uid() in(c.user_a,c.user_b)));
create policy "messages members send" on messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from conversations c where c.id=conversation_id and auth.uid() in(c.user_a,c.user_b)));
create policy "moderation log admin" on moderation_log for select to authenticated using(is_admin());
create policy "communities read" on communities for select to authenticated using(true);
insert into communities(name,description,category) values('Emo Underground','Alternative culture and music','Culture'),('Pixel Arcade','Retro games','Gaming'),('Web Relics','Old web nostalgia','Technology') on conflict do nothing;
grant execute on function is_admin() to authenticated;grant execute on function get_or_create_conversation(uuid) to authenticated;grant execute on function moderate_remove_post(uuid,text) to authenticated;
